-- 0015_no_third_party_benchmarks.sql
-- Supabase Schema Teardown. Generated by tools/build_sql.py; edit there, not here.

-- Targets are Supabase's own numbers or our rule of thumb. No unsourced third-party benchmarks.

insert into public.lessons (id, chapter, stage, title, move, evidence_query, evidence, mechanism, steps, metric, dont_copy_if, target, target_source) values
  (1, 'taglines', 'pre-launch', 'Test positioning like a feature', 'Copplestone changed one line of homepage copy, from "realtime postgres." to "The opensource Firebase alternative." The next day an early user posted Supabase to Hacker News, and it reached the top.', 'taglines_history', '8 hosted databases before the change, 800 within three days (Contrary Research). The new line and the Hacker News post came a day apart, so the credit can''t be split. Copplestone credits the positioning: "product-market fit often is just like a product-positioning fit" (First Round Review).', 'The first line was a feature attached to a technology. The second named a tool the reader already used and a reason to switch. Four words moved it from feature differentiation to a specific segment: people who like Firebase but fear lock-in.', 'Write three one-line positionings: a feature line, a category line ("the open source X alternative") and a problem line.
Put each in front of 10 developers who match your ideal customer. Ask only: "What do you think this does, and who''s it for?" Count correct answers.
Ship the winner to your homepage for two weeks, then the runner-up for two weeks. Compare signups per unique visitor.
Keep the losing lines in a file. Positioning is a backlog, not a decision.', 'Signup rate per unique visitor (homepage to account created).', 'You change the line every week. Supabase kept "Firebase alternative" in its page title for five years.', '7 of 10 developers describe it correctly in one sentence. Below 5, the line isn''t working yet.', 'Our rule of thumb'),
  (2, 'taglines', 'pre-launch', 'Borrow a category before you build one', '"Firebase alternative" borrowed a category developers already understood instead of inventing one.', 'taglines_history', 'Six years later, AI models still make the link. Asked for a Firebase alternative, three Claude models named Supabase in all 143 answers and as the first alternative in 120 (84%). Preliminary: our own study, Claude models only.', 'A new category costs you a paragraph of education per reader. A borrowed one costs two words. Early on, clarity beats differentiation: nobody can prefer what they can''t classify.', 'Finish the sentence "We''re the ____ alternative" with a tool your ideal customers know. If none fits, try "____ for ____": an incumbent plus a segment it ignores.
Add one reason to switch that hits the incumbent''s known weakness (Supabase: lock-in).
Build an honest "You vs Incumbent" page that admits where the incumbent wins. It earns trust and ranks for the exact search people type.
Plan your exit from the borrowed category. Supabase moved to "Build in a weekend. Scale to millions." in 2022 and "The Postgres Development Platform." in 2025.', 'Share of signups from comparison or "alternative" searches.', 'The incumbent is loved and has no obvious weakness. "Alternative" only pulls people who already want to leave.', 'Your comparison page ranks on page one for "<incumbent> alternative" within six months.', 'Our rule of thumb'),
  (3, 'postgres_bet', 'pre-launch', 'Own day zero', 'Get chosen when the project starts, then never give the project a reason to leave.', 'time_to_first_row', 'Copplestone timed AWS himself: launching an RDS instance, connecting a tool and inserting one row took about 8.5 minutes. The early target was under a minute; today it''s about 5 seconds. They never said the number out loud (YC Startup School).', 'Developers usually pick a backend at the start of a project, in the first hour of trying things. Being fastest then is how you get picked. Building on Postgres meant Supabase didn''t lose the project later, when it needed to scale.', 'Stopwatch audit: three people who have never used your product, screen recorded, from your homepage to the first moment of real value. Do the same for your top competitor.
Log every step: each click, form field, email verification, docs page and error. Mark each one remove, defer or keep.
Defer everything that isn''t needed for first value: credit card, team setup, SSO, onboarding surveys.
Set a target in seconds or minutes, put it on the wall, and re-run the stopwatch every month.', 'Median time to first value for new signups, and the share who reach it in their first session.', 'Your value genuinely needs integration work (a scanner on a real codebase, observability on production traffic). Then shrink time to first proof instead: a demo dataset, a sandbox, a sample repo.', 'Under 10 minutes from your homepage to first value, with no help from you. Supabase got it to seconds.', 'Our rule of thumb'),
  (4, 'postgres_bet', 'launch', 'Build on something you don''t own', 'Supabase bet on Postgres instead of building its own database, and made leaving easy: it''s just Postgres, take your data and go.', 'hn_split', 'Of the 61 Hacker News stories over 100 points that link to or name Supabase, 29 (almost half) never say Supabase in the headline. They''re about Postgres.', 'Nobody owns Postgres, so everyone contributes to it, and every hyperscaler has to offer a strong Postgres. Copplestone calls it game theory. The engine keeps improving without Supabase paying for it. Portability lowers the fear of trying, and content about the standard reaches people who would never click a vendor post.', 'Name the open standard under or next to your product. If there isn''t one, name the open format your users'' data lives in.
Write the exit doc, "How to leave us", as clearly as your quickstart. Link it from pricing.
Plan 10 posts that teach the standard itself, with your product in the last paragraph or not at all.
Contribute upstream, visibly. One merged PR to the standard is worth ten posts about your product.', 'Share of content traffic from posts that don''t name your product, and the signups they drive.', 'Your moat is the proprietary format. Then portability is a giveaway: borrow trust another way (compliance, benchmarks, named customers).', 'A third of your content traffic comes from posts that don''t name your product.', 'Our rule of thumb'),
  (5, 'launch_weeks', 'launch', 'Make shipping an event, while it still works', 'Batch a quarter''s releases into one named Launch Week, one launch a day.', 'launch_week_fade', 'Average star lift per launch week fell every year we measured: 3.8x in 2021, then 2.0x, 1.5x, 1.2x, and 1.0x in 2025 (data to July 2025). Copplestone still saw "these 20% bumps each time" (First Round Review), so the ritual kept paying; it stopped moving stars.', 'Five launches in five days gives the community a reason to look every morning and gives newsletter writers a story instead of a changelog line. Early on, attention is scarce and the format concentrates it. Stars also flatten as a repo gets big, so measure what you sell: signups and activations, not stars.', 'Keep a running list of everything you ship. At quarter end, pick the five best. If you can''t find five, run a launch day.
One item per day: a post, a demo under 60 seconds, and docs live before the post goes out.
Pre-brief 10 friendly developers and 3 newsletter writers a week ahead.
Measure lift against your own baseline (the 28 days before). Change the format when lift drops below 1.5x twice running.', 'Signups per day during the week divided by the daily average of the prior 28 days.', 'You ship once a quarter anyway, or your launches are invisible to users. Five weak launches teach your audience to ignore you.', '1.5x your 28-day signup baseline during the week. Below that twice running, change the format.', 'Our rule of thumb'),
  (6, 'origins', 'launch', 'Mean it on open source', 'Open source the real product, not a demo. Everything Supabase builds is MIT, Apache 2 or PostgreSQL licensed, except the platform and billing code (First Round Review).', 'origins_timeline', 'The May 2020 Hacker News post brought 522 new stars in a day, still the repo''s best day in our data (to September 2025). The repo has about 112K stars today.', 'Developers trust code they can read and self-host. That trust is what let a team of about three get adopted by teams that would never buy from a startup.', 'Decide what''s open by one rule: is the open part useful on its own? If it''s a crippled demo of the paid product, keep it closed. Developers will find out.
Charge for operations (hosting, scale, compliance, support), not for features ripped out of the core.
Make self-hosting documented and boring. Most people who can self-host won''t, and those who do become your loudest advocates.', 'Outside contributors per month, and self-host to cloud conversions.', 'Open source isn''t table stakes in your category. It''s a distribution and trust strategy, not a moral requirement, and it costs real support time.', 'Outside contributors every month, and every issue answered within a working day.', 'Our rule of thumb'),
  (7, 'sales_motion', 'early-revenue', 'Free until it''s real', 'A generous free tier, with pricing that starts when the app has users, not while the developer is exploring.', 'revenue', 'No revenue for about 18 months, then roughly $1M ARR by the end of the first year of charging and about $7.5M the year after, by Copplestone''s rough recollection (YC Startup School).', 'Developers explore with side projects. Charging during exploration kills adoption; charging at production captures value when the user has budget and a reason to pay.', 'Find your production signal: the usage pattern that means "this is real" (traffic, team size, uptime needs, data volume).
Put your first paid line just past it. Everything before it is free.
Make the bill predictable: caps, spend alerts, no surprise invoices. One surprise bill on Hacker News costs more than a year of upgrades.
List the free projects that cross the production signal and don''t upgrade. That''s your sales pipeline.', 'Free to paid conversion among projects past the production signal (not among all signups).', 'You can''t fund 18 months without revenue. Supabase did it on 2020 and 2021 money. Check what your next investors expect to see, and start charging from your production signal early.', 'Supabase''s pace: about $1M ARR by the end of its first year of charging.', 'Copplestone, YC Startup School'),
  (8, 'sales_motion', 'early-revenue', 'Sales as support', 'Sales reach out when usage says the customer needs help (disk thrashing, CPU limits), not when a lead score says they might buy. Copplestone: "our sales actually just looks like support."', 'sales_cohorts', 'Product triggers send an automated email to accounts that fit. Accounts that talked to the success team grew usage 125% quarter on quarter; accounts that didn''t reply grew 25% (First Round Review). The groups choose themselves, so treat the gap as a direction, not proof. The team is paid only on the incremental uplift over the non-responders.', 'The message lands when the developer has a problem, so it reads as help, not a pitch. Paying on incremental uplift stops the team claiming growth that would have happened anyway.', 'Pick three triggers: near a plan limit, an error spike, usage doubling week on week.
When one fires, a founder sends a plain-text note: what you noticed, one specific suggestion, an offer to talk. No deck.
Hold back a random 20% of triggered accounts and don''t contact them. That''s a stricter control than Supabase''s, and it tells you what the outreach is worth.
Hire for this only once the founder-run version beats the control. Pay on that uplift.', '90-day expansion of contacted accounts vs the control group.', 'Fewer than about 50 accounts hit a trigger each month. Then just talk to all of them: a control group that small tells you nothing.', 'Contacted accounts expand at least twice as much as the control group at 90 days.', 'Our rule of thumb'),
  (9, 'ai_waves', 'scale', 'Be legible to AI', 'Supabase became the default backend for AI app builders and coding agents, which now create most of its new databases.', 'ai_waves', 'In our preliminary study of three Claude models, Supabase was the first backend named in 160 of 180 generic "database plus login" answers (89%) and in 0 of 84 control prompts. Copplestone: "The LLM slurped up a lot of Supabase."', 'Years of open source code, Reddit threads and GitHub discussions became training data. Then Supabase built for agents directly: a CLI and an MCP server an agent can drive.', 'Ask three AI models the question your ideal customer would ask, 10 times each. Count how often you''re named, and first. That''s your baseline (our prompts and scripts are open source).
Publish llms.txt (a proposed standard) and make your docs readable as plain text, one concept per page.
Make the product drivable without a browser: a CLI with clear errors, an OpenAPI spec, an MCP server if agents would use it.
Answer questions in public (GitHub discussions, Stack Overflow, Reddit), not only in a Discord no model will ever read.
Re-run the baseline every quarter.', 'Share of AI answers that name you first, across your 10 most important prompts.', 'You think it''s a trick. Models recommend what the public internet already recommends. This is the teach-the-standard strategy with a new reader.', 'Named first in at least half of your 10 core prompts, on the model your users use most.', 'Our rule of thumb'),
  (10, 'rounds', 'always', 'Raise for leverage, operate like you didn''t', 'Supabase raised over $1B and still runs fully remote, with no offices, little marketing spend and decisions written down in Slack and Notion. Copplestone: "the money shouldn''t change how you operate."', 'rounds', 'The $6M seed came from Coatue, a hedge fund that barely cared at that size and got much more interested as public markets came into view. Today: about 350 people in 60+ countries, and Pro still starts at $25 a month.', 'Money buys runway and options, not product-market fit. Keeping a small team''s habits (founders on user calls, written decisions, no paid acquisition until retention holds) is what kept every other lesson working at scale.', 'Before every hire, write one sentence: "This is burning, and it will keep burning without this person." If you can''t, don''t hire.
Keep founder hours on user calls fixed each week (start with five), however much you raise.
Pick investors whose interest grows as you do.
No paid acquisition until month-3 retention holds.', 'Month-3 retention: of developers active in their first month, how many are still active in month 3?', 'A competitor is buying the category and the window is closing. Then speed beats thrift.', 'Steady or rising for three cohorts in a row before you spend on acquisition.', 'Our rule of thumb'),
  (11, 'origins', 'pre-launch', 'Pick an ideal customer that grows into big bills', 'Supabase targeted high-growth, venture-backed startups from day one: the companies whose free projects become big production databases.', 'origins_timeline', 'Copplestone on their own YC batch: "I think there was zero. Uh well there was one company." He now puts it at over 60% of each batch; Supabase''s last published count was 55% of the most recent batch (October 2025).', 'Startups adopt fast, decide without procurement and grow their usage on their own. Pick the segment whose success becomes your revenue, and your best customers arrive with the next batch, not the next sales hire.', 'Describe your ideal customer in one sentence: who they are, the trigger that makes them look, and why their usage grows without you.
Name 20 teams that fit. If you can''t name 20, the description is too narrow or too vague.
Find where they gather (an accelerator batch, a framework community, a Discord) and show up there every week.
Track which of the 20 adopt, and which of those grow. Rewrite the sentence every quarter.', 'Share of new signups that match your ideal-customer sentence, and their usage growth after 90 days.', 'Your best-fit buyer churns as it grows (it graduates to building in house). Then pick the segment that stays, even if it adopts more slowly.', 'Within six months, 10 of your 20 named teams have tried it and 3 run it in production.', 'Our rule of thumb'),
  (12, 'postgres_bet', 'launch', 'The CEO is the channel', 'Copplestone read Hacker News about three times a day, watched the Show HNs, and posted many of Supabase''s biggest stories himself.', 'hn_split', 'Of the 61 Hacker News stories over 100 points that link to or name Supabase, he posted 18, including two of the top three. 13 of his 18 never mention Supabase in the headline. Nobody else posted more than 4.', 'Early on, nobody trusts a company account; they trust a builder who shows up. A founder posting the real work and answering every reply is the cheapest distribution a two-person team has, and it doubles as customer research.', 'Pick the one place your ideal customers read every day (Hacker News, a subreddit, X, a Discord) and read it daily.
Post three times a week as yourself: what you built, what broke, what you learned. Not announcements.
Answer every reply within a day. The replies are your customer research.
Once a quarter, post something genuinely useful about the standard, not the product, and aim it at the front page.', 'Signups attributed to founder posts, and replies per post.', 'You hate writing in public and it shows. Then make your most credible engineer the voice: authenticity matters more than the title.', 'Three real posts a week, and one front-page attempt a quarter.', 'Our rule of thumb')
on conflict (id) do update set chapter = excluded.chapter, stage = excluded.stage, title = excluded.title, move = excluded.move, evidence_query = excluded.evidence_query, evidence = excluded.evidence, mechanism = excluded.mechanism, steps = excluded.steps, metric = excluded.metric, dont_copy_if = excluded.dont_copy_if, target = excluded.target, target_source = excluded.target_source;

update public.principles set title = 'Test positioning like a feature', body = 'Copplestone changed one line of homepage copy, from "realtime postgres." to "The opensource Firebase alternative." The next day an early user posted Supabase to Hacker News, and it reached the top.', how = 'Write three one-line positionings: a feature line, a category line ("the open source X alternative") and a problem line.' where id = 1;
update public.principles set title = 'Borrow a category before you build one', body = '"Firebase alternative" borrowed a category developers already understood instead of inventing one.', how = 'Finish the sentence "We''re the ____ alternative" with a tool your ideal customers know. If none fits, try "____ for ____": an incumbent plus a segment it ignores.' where id = 2;
